import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"Product Scope And Architecture","description":"","frontmatter":{"docLocale":"en","counterpart":"/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"en/architecture/lab-word.md","filePath":"en/architecture/lab-word.md"}'),i={name:"en/architecture/lab-word.md"};function s(o,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="product-scope-and-architecture" tabindex="-1">Product Scope And Architecture <a class="header-anchor" href="#product-scope-and-architecture" aria-label="Permalink to &quot;Product Scope And Architecture&quot;">​</a></h1><p>Lab Word is a laboratory digital twin. The application currently provides persistent Labs, independent Entities, multi-node scenes, a server Asset Library, versioned definitions, layout editing and manual relationship registration, and backend lighting programs. See the <a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/CONTEXT.md" target="_blank" rel="noreferrer">glossary</a>.</p><h2 id="models-and-equipment" tabindex="-1">Models And Equipment <a class="header-anchor" href="#models-and-equipment" aria-label="Permalink to &quot;Models And Equipment&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab ──registers──&gt; Entity &lt;──defined by── Asset</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    └──represented by Scene Node &lt;──appearance── Asset Representation</span></span></code></pre></div><p>This Foundation V1 identity relationship is implemented: an Equipment Model is a 3D representation, and an Equipment Instance is a device Entity. Scene Node identity and placement are independent of device identity. Multiple devices can share a model, and one device can have multiple nodes. Registration pins a definition version and snapshot. Simulated and physical objects have separate identities, and static objects require no Binding.</p><h2 id="existing-implementation-and-planned-integration" tabindex="-1">Existing Implementation And Planned Integration <a class="header-anchor" href="#existing-implementation-and-planned-integration" aria-label="Permalink to &quot;Existing Implementation And Planned Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Current state</th><th>Future responsibility</th></tr></thead><tbody><tr><td>Universal shell, identity, membership, knowledge</td><td>Existing application code</td><td>Host Lab and provide shared capabilities</td></tr><tr><td>Lab and persistent Asset Library</td><td>Members/Agents share worlds, layouts, relationships, files, lighting and temperature APIs, and reliable subscriptions</td><td>More programs and history</td></tr><tr><td>Lab navigation and default entry after login</td><td>Integrated through explicit composition</td><td>Preserve shell and Lab ownership</td></tr><tr><td>Foundation V1</td><td>Experience accepted; spec/tickets published</td><td>Build persistent worlds and virtual devices</td></tr><tr><td>Physical devices and protocols</td><td>Future scope</td><td>Add source adapters and execution contracts</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>chooses the existing SaaS foundation: Lab owns equipment and layout behavior while Core owns common identity and membership. See <a href="./project-structure">project structure</a> for integration locations.</p><h2 id="presentation-boundaries" tabindex="-1">Presentation Boundaries <a class="header-anchor" href="#presentation-boundaries" aria-label="Permalink to &quot;Presentation Boundaries&quot;">​</a></h2><p>The Lab entry has an object directory, multi-node scene and Inspector. Placement, configuration and references persist across browsers and Agents. Pointer transforms edit only Placement. Located-in, contains and simulation relationships are explicitly registered with manual provenance; spatial relationships jointly reject invalid cycles. Independent copies create new Entities, while additional representations and node removal retain identity. Version conflicts keep the page draft for an explicit reload and retry; see the <a href="./../tutorials/edit-layout">layout tutorial</a>. Definition support, Binding implementation and current executability remain separate; absent observations are unknown. Independent backend lights distinguish command acceptance from observations, retain the last report when stopped and require explicit startup after interruption; see the <a href="./../tutorials/backend-lights">lighting tutorial</a>. Layout versions remain separate from runtime state. <a href="./../tutorials/reliable-sync">World subscriptions</a> provide persistent versions, property updates, bounded queues, snapshot recovery and revocation of existing access. Execution service readiness and persistent capability permission jointly determine operability. Centrifuge tasks and history follow in later slices. The asset library retains preview at <code>/lab/asset</code>; Core owns file lifecycles and Lab owns stable references.</p><p>Backend <a href="./../tutorials/continuous-temperature">temperature sensors</a> sample independently at 1Hz. Each property retains value, unit, source, timestamps and quality. Heartbeats do not refresh old measurements. Stopping a source keeps its last value. The report deadline determines expiry. Expiry advances the world version and preserves layout drafts.</p><p>The implementation preserves source scale, reports external-resource dependencies, absent geometry and decoder failures, and keeps the previous usable model on failure. Each node loads and releases independent model resources; selecting one instance does not rewrite another&#39;s materials. World snapshots return assets referenced by nodes and unplaced objects, so model recovery does not depend on the first catalog page.</p><p>Three.js code is loaded with the Lab page and checked against production bundle budgets. Preview builds and software-rendering measurements do not establish target-hardware performance.</p><h2 id="continue-development" tabindex="-1">Continue Development <a class="header-anchor" href="#continue-development" aria-label="Permalink to &quot;Continue Development&quot;">​</a></h2><p>Follow the <a href="./../guides/lab-viewer">viewer guide</a> for current behavior. Foundation V1 continues through <a href="https://github.com/CaiZongyuan/labworld/issues/1" target="_blank" rel="noreferrer">spec #1</a> and its implementation tickets; start with the <a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/docs/handoffs/digital-twin-foundation-v1.md" target="_blank" rel="noreferrer">developer handoff</a>. <a href="./module-boundaries">Module boundaries</a> define ownership.</p><hr><p>Source version：<code>ddaf175ca215</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/docs/architecture/lab-word.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,17)])])}const b=t(i,[["render",s]]);export{h as __pageData,b as default};
